html/assets/style.css:
body{font-family:system-ui,sans-serif;max-width:52rem;margin:2rem auto;padding:0 1rem;line-height:1.5}
nav.toc{font-size:.9rem}
.broken{color:#b00020;text-decoration:underline dotted}
pre{overflow-x:auto;background:#f5f5f5;padding:.5rem}
blockquote{border-left:3px solid #ccc;margin-left:0;padding-left:1rem}
table{border-collapse:collapse}td,th{border:1px solid #ccc;padding:.2rem .4rem}
footer{margin-top:3rem;font-size:.8rem;color:#666}

